$baseUrl=rtrim((string)($cfg['base_url']??''),'/');$title=(string)($cfg['title']??'XLX Modern Admin');$adminSlug=trim((string)($cfg['admin_slug']??'admin'),'/');$adminPath='/'.$adminSlug.'/';$testPaths=is_array($cfg['test_paths']??null)?$cfg['test_paths']:[];

