function h(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function ip():string{return $_SERVER['REMOTE_ADDR']??'unknown';}
function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return(string)$_SESSION['csrf'];}
function csrf_ok(string $v):bool{return isset($_SESSION['csrf'])&&hash_equals((string)$_SESSION['csrf'],$v);}
function auth():bool{if(($_SESSION['auth']??false)!==true)return false;$n=time();$l=(int)($_SESSION['last']??0);$b=(int)($_SESSION['born']??0);if(!$l||!$b||$n-$l>1200||$n-$b>28800){$_SESSION=[];session_destroy();return false;}$_SESSION['last']=$n;return true;}
function audit(string $e):void{@file_put_contents(STATE.'/audit.log',date('c').' ip='.ip().' event='.preg_replace('/[^A-Za-z0-9_.:-]/','_',$e)."\n",FILE_APPEND|LOCK_EX);}
function ratefile():string{return STATE.'/login-'.hash('sha256',ip()).'.json';}
function rate():array{$f=ratefile();$d=is_file($f)?json_decode((string)@file_get_contents($f),true):null;return is_array($d)?$d:['fails'=>0,'first'=>0,'locked'=>0];}
function fail_login():void{$s=rate();$n=time();if(empty($s['first'])||$n-(int)$s['first']>900)$s=['fails'=>0,'first'=>$n,'locked'=>0];$s['fails']=(int)$s['fails']+1;if($s['fails']>=5)$s['locked']=$n+900;@file_put_contents(ratefile(),json_encode($s),LOCK_EX);}
function runh(string $c,array $args=[]):array{
 $allowed=['status','listeners','logs','backups','restart','health-status','radioid-status','radioid-search','radioid-save','radioid-delete','radioid-refresh','radioid-check','access-status','access-add-white','access-delete-white','access-add-black','access-delete-black','access-interlink-add','access-interlink-delete'];
 if(!in_array($c,$allowed,true))return[false,'',64];
 $cmd='/usr/bin/sudo -n '.escapeshellarg(HELPER).' '.escapeshellarg($c);
 foreach($args as $a)$cmd.=' '.escapeshellarg((string)$a);
 $o=[];$r=0;exec($cmd.' 2>&1',$o,$r);return[$r===0,implode("\n",$o),$r];
}
function kv(string $s):array{$r=[];foreach(preg_split('/\R/',$s)?:[]as$l){if(str_contains($l,'=')){[$k,$v]=explode('=',$l,2);$r[trim($k)]=trim($v);}}return$r;}
function jr(string $c,array $args=[]):array{[$ok,$out,$rc]=runh($c,$args);$j=json_decode($out,true);return[$ok&&is_array($j),is_array($j)?$j:[],trim($out),$rc];}
function helper_reason(string $detail,string $fallback):string{
 $d=trim($detail);
 $map=[
  'Radio ID já pertence'=>'Este Radio ID já pertence a outro cadastro.',
  'Radio ID deve ter 7 dígitos'=>'O Radio ID deve ter 7 dígitos ou ficar vazio.',
  'indicativo original inválido'=>'O indicativo original é inválido.',
  'indicativo inválido'=>'O indicativo informado é inválido.',
  'cadastro original não foi localizado de forma única'=>'O cadastro selecionado não pôde ser identificado de forma única. Pesquise novamente e tente outra vez.',
  'indicativo já existe'=>'Este indicativo já possui cadastro. Pesquise o indicativo e edite o registro existente.',
  'nome, cidade, estado e país são obrigatórios'=>'Nome, cidade, estado e país são obrigatórios.',
  'campos não podem conter vírgulas'=>'Os campos não podem conter vírgulas ou quebras de linha.',
  'reconstrução SQL falhou'=>'A sincronização do banco SQL falhou. A base anterior foi restaurada automaticamente.',
  'novo banco SQL falhou na integridade'=>'O novo banco SQL não passou na verificação de integridade. A base anterior foi restaurada.',
  'estrutura do novo banco SQL é incompatível'=>'O novo banco SQL apresentou estrutura incompatível. A base anterior foi restaurada.',
  'gerador SQL tem formato inesperado'=>'O gerador SQL atual não é compatível com a sincronização segura. Nenhuma alteração foi mantida.',
  'outra operação de indicativos está em andamento'=>'Já existe outra operação de indicativos em andamento. Tente novamente após ela terminar.'
 ];
 foreach($map as $needle=>$message){if(stripos($d,$needle)!==false)return$message;}
 return$fallback;
}
function probe(string $url):array{$o=[];$r=0;exec('/usr/bin/curl --silent --show-error --location --connect-timeout 4 --max-time 8 --output - --write-out '.escapeshellarg("\n__C__:%{http_code}").' '.escapeshellarg($url).' 2>&1',$o,$r);$x=implode("\n",$o);$c=0;if(preg_match('/\n__C__:(\d{3})\s*$/',$x,$m)){$c=(int)$m[1];$x=preg_replace('/\n__C__:\d{3}\s*$/','',$x)??$x;}return[$c,$x,$r];}
function bytesv(int $b):string{if($b<1024)return$b.' B';if($b<1048576)return number_format($b/1024,1,',','.').' KB';return number_format($b/1048576,1,',','.').' MB';}
function radioid_api_lookup(string $call):array{
 $call=strtoupper(trim($call));
 if(!preg_match('/^[A-Z0-9]{3,8}$/',$call))return[false,[],'Indicativo inválido.'];
 $url='https://radioid.net/api/users?'.http_build_query(['callsign'=>$call,'callsign_sel'=>'=','page'=>1,'per_page'=>20]);
 $o=[];$r=0;
 $cmd='/usr/bin/curl --silent --show-error --location --connect-timeout 4 --max-time 10 --header '.escapeshellarg('Accept: application/json').' --user-agent '.escapeshellarg('XLX-Modern-Admin/1.0').' '.escapeshellarg($url);
 exec($cmd.' 2>&1',$o,$r);
 if($r!==0)return[false,[],'Não foi possível consultar RadioID.net.'];
 $j=json_decode(implode("\n",$o),true);
 if(!is_array($j)||!isset($j['results'])||!is_array($j['results']))return[false,[],'Resposta inesperada da API RadioID.net.'];
 return[true,$j['results'],''];
}
